// a glass curtain wall on a plan polygon: the wall, vertical mullions every `sp` m and floor lines every `fh` m
function curtainP(B, P, y0, y1, glass, mull, sp, fh, edges){
  prismP(B.p(glass), P, y0, y1);
  if (mull){ mullP(B.p(mull), P, y0, y1, sp, 0.22, 0.05, edges); if (fh) bandsP(B.p(mull), P, y0, y1, fh, 0.28, 0.06, edges); }
}
