  { const o = B.p(grass); const n = 10; for (let i = 0; i < n; i++){ const a0 = i/n*TAU, a1 = (i + 1)/n*TAU; triP(o, [-1, 0.22, 46], [-1 + Math.cos(a1)*4.5, 0.22, 46 + Math.sin(a1)*4.5], [-1 + Math.cos(a0)*4.5, 0.22, 46 + Math.sin(a0)*4.5]); } }
  B.flush(g);
