// ===== 70 Pine Street (Clinton & Russell, Holton & George, 1932): 290 m (952 ft) to the spire tip, 67 storeys. Art Deco:
// limestone and pale brick piers rising in many small setbacks (OSM parts, 30-odd of them), up to the glass-enclosed
// observatory "solarium" in the crown at ~245 m and a steel spire. Night: the crown and the glass lantern glow.
// Frame: rot -38.6 deg; -z = Pine Street (north), +z = Cedar Street, +x = Pearl Street (east).
LANDMARKS.ny70pine = {zh:'松树街70号', en:'70 Pine Street', cat:'old', r:65, h:290,
  lt:{m:1, c:'#fff0d6', k:0.55, fh:3.8, cw:1.9}, build(){
  const g = new THREE.Group(), B = mkB(), D = FD.ny70pine;
  const lime = {c:'#d6cfbf', m:1, fh:3.8, cw:1.9}, brick = {c:'#cbbfa8', m:1, fh:3.8, cw:1.9}, win = {c:'#47494b', m:1, fh:3.8, cw:1.9};
  const crown = {c:'#ddd6c6', m:0, lk:1.2, lc:'#fff2dc', glow:'#fff0d8', gk:0.3}, glass = {c:'#8a9aa3', glow:'#ffe7c2', gk:0.85}, steel = {c:'#b8bdc0', m:0, lk:0.9}, red = {c:'#c22', glow:'#ff2a1a', gk:2.2};
  const parts = D.parts.filter(p => p[1] <= 242);
  decoParts(B, parts, (b, t) => t <= 45 ? lime : t >= 224 ? crown : brick, win, {fh:3.8, sp:1.75, trim:lime});
  // the crown: stepped stages over the 242 m roof, the glass solarium, the spire
  const top = D.parts.filter(p => p[1] > 242).sort((a, b) => a[0] - b[0]);
  for (const [b, t, P] of top){ const isGlass = t <= 252; prismP(B.p(isGlass ? glass : crown), P, b, t); if (isGlass) mullP(B.p(crown), P, b, t, 1.6, 0.25, 0.05); }
  { const P = top[top.length - 1][2], c = P.reduce((s, p) => [s[0] + p[0]/P.length, s[1] + p[1]/P.length], [0, 0]);
    LCylD(g, 0.15, 0.9, 27, c[0], 263, c[1], steel, 8); for (let k = 0; k < 4; k++) LCylD(g, 1.2 - k*0.22, 1.2 - k*0.22, 0.5, c[0], 266 + k*5, c[1], steel, 8);
    LSphD(g, 0.35, c[0], 290, c[1], red, 1, 6); }
  neighboursP(B, D.nb);
  B.flush(g);
  return g; }};
place('ny70pine');

// ===== New York Stock Exchange (George B. Post, 1903) with its 1922 annex (11 Wall Street). White Georgia marble. On Broad
